as imported(game_card_key text, name text, description text, mana integer, damage_type integer, base_damage integer, percent_damage numeric, damage_multiplier numeric, character_class text, source_pack text, source_asset_path text, minimum_question_tier integer, maximum_question_tier integer, attack_vfx_type integer, icon_asset_guid text, icon_sprite_file_id text, card_definition jsonb)
on conflict (game_card_key) do update set
  name = excluded.name,
  description = excluded.description,
  mana = excluded.mana,
  damage_type = excluded.damage_type,
  base_damage = excluded.base_damage,
  percent_damage = excluded.percent_damage,
  damage_multiplier = excluded.damage_multiplier,
  character_class = excluded.character_class,
  source_pack = excluded.source_pack,
  source_asset_path = excluded.source_asset_path,
  minimum_question_tier = excluded.minimum_question_tier,
  maximum_question_tier = excluded.maximum_question_tier,
  attack_vfx_type = excluded.attack_vfx_type,
  icon_asset_guid = excluded.icon_asset_guid,
  icon_sprite_file_id = excluded.icon_sprite_file_id,
  card_definition = excluded.card_definition,
  updated_at = now();
commit;
select character_class, count(*) as imported_cards
from public.cards where source_pack = 'CARDS'
group by character_class order by character_class;
